js:function f() {
    var status = ${CONN_LATEST_STATUS};
    var color, icon;
    if (typeof(status) != 'undefined' && status != null) {
      status = status.toString();
      if (status === '0') {
          color = 'danger';
          icon = 'fa fa-times-circle';
      } else if (status === '1') {
          color = 'success';
          icon = 'fa fa-check-circle';
      } else {
          color = 'warning';
          icon = 'fa fa-question-circle';
      }
    } else {
          color = 'warning';
          icon = 'fa fa-question-circle';
      }

    return '<span class="text-' + color + '"><i class="' + icon + '"></i></span>';
}

js:function f (){
    var CONN_RATE=${CONN_RATE};
    if (!CONN_RATE){
      text='未测试';
      css = 'secondary';
      style='fa-times';
    } else if (CONN_RATE>=50){
      text= CONN_RATE +'%';
      css = 'primary';
      style='fa-check';
    } else if (CONN_RATE>=0){
      text= CONN_RATE  +'%';
      css = 'warning';
      style='fa-times';
    } else {
      text='未测试';
      css = 'secondary';
      style='fa-times';
    }
    return '<span class="text-'+css+'">'+text+'</span>';
  }
